import React, { useEffect, useState } from "react";
import axios from "axios";

const API = "http://localhost:5000";

export default function AdminPanel() {
  const [users, setUsers] = useState([]);
  const [filter, setFilter] = useState("all");
  const [loading, setLoading] = useState(true);
  const [toast, setToast] = useState("");
  const [bulkScore, setBulkScore] = useState(80);
  const [bulkLoading, setBulkLoading] = useState(false);
  const [search, setSearch] = useState("");

  /* ── Fetch all users ── */
  const fetchUsers = async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${API}/admin/users`);
      setUsers(Array.isArray(res.data) ? res.data : []);
    } catch {
      showToast("❌ Failed to load users. Is backend running?");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const showToast = (msg) => {
    setToast(msg);
    setTimeout(() => setToast(""), 3500);
  };

  /* ── Approve / Reject ── */
  const handleAction = async (id, status, name) => {
    try {
      const res = await axios.post(`${API}/admin/update-status`, {
        id,
        status,
      });
      if (res.data.success) {
        setUsers((prev) =>
          prev.map((u) => (u.id === id ? { ...u, payment_status: status } : u)),
        );
        showToast(
          status === "approved"
            ? `✅ ${name} approved — ID card unlocked`
            : `❌ ${name} rejected — UTR blacklisted`,
        );
      }
    } catch {
      showToast("❌ Action failed. Try again.");
    }
  };

  /* ── Bulk auto-approve ── */
  const handleBulkApprove = async () => {
    setBulkLoading(true);
    try {
      const res = await axios.post(`${API}/admin/bulk-approve`, {
        threshold: bulkScore,
      });
      if (res.data.success) {
        showToast(
          `✅ Bulk approved ${res.data.approved} user(s) with score ≥ ${bulkScore}`,
        );
        fetchUsers();
      }
    } catch {
      showToast("❌ Bulk approve failed.");
    }
    setBulkLoading(false);
  };

  /* ── Re-analyze UTR ── */
  const handleReanalyze = async (id, name) => {
    try {
      const res = await axios.post(`${API}/admin/reanalyze/${id}`);
      if (res.data.success) {
        setUsers((prev) =>
          prev.map((u) =>
            u.id === id
              ? { ...u, utr_score: res.data.score, utr_flags: res.data.flags }
              : u,
          ),
        );
        showToast(
          `🔬 ${name} re-analyzed — Score: ${res.data.score}/100 (${res.data.verdict})`,
        );
      }
    } catch {
      showToast("❌ Re-analysis failed.");
    }
  };

  /* ── Computed lists ── */
  const filtered = users.filter((u) => {
    const matchFilter = filter === "all" || u.payment_status === filter;
    const matchSearch =
      !search ||
      u.name?.toLowerCase().includes(search.toLowerCase()) ||
      u.utr_number?.toLowerCase().includes(search.toLowerCase()) ||
      u.email?.toLowerCase().includes(search.toLowerCase());
    return matchFilter && matchSearch;
  });

  const counts = {
    all: users.length,
    pending: users.filter((u) => u.payment_status === "pending").length,
    approved: users.filter((u) => u.payment_status === "approved").length,
    rejected: users.filter((u) => u.payment_status === "rejected").length,
  };

  /* ── Score color ── */
  const scoreColor = (s) =>
    s >= 75 ? "#166534" : s >= 45 ? "#854d0e" : "#b91c1c";
  const scoreBg = (s) =>
    s >= 75 ? "#f0fdf4" : s >= 45 ? "#fefce8" : "#fef2f2";
  const scoreBorder = (s) =>
    s >= 75 ? "#86efac" : s >= 45 ? "#fde047" : "#fca5a5";

  /* ── Status badge ── */
  const StatusBadge = ({ status }) => {
    const map = {
      pending: {
        bg: "#fefce8",
        color: "#854d0e",
        border: "#fde047",
        label: "Pending",
      },
      approved: {
        bg: "#f0fdf4",
        color: "#166534",
        border: "#86efac",
        label: "Approved",
      },
      rejected: {
        bg: "#fef2f2",
        color: "#b91c1c",
        border: "#fca5a5",
        label: "Rejected",
      },
    };
    const c = map[status] || map.pending;
    return (
      <span
        style={{
          padding: "3px 10px",
          borderRadius: 20,
          fontSize: 11,
          fontWeight: 600,
          backgroundColor: c.bg,
          color: c.color,
          border: `1px solid ${c.border}`,
        }}
      >
        {c.label}
      </span>
    );
  };

  /* ════════════════════════
     RENDER
  ════════════════════════ */
  return (
    <div
      style={{
        minHeight: "100vh",
        backgroundColor: "#f3f4f6",
        fontFamily: "system-ui, sans-serif",
      }}
    >
      {/* Toast */}
      {toast && (
        <div
          style={{
            position: "fixed",
            bottom: 24,
            right: 24,
            zIndex: 999,
            background: "#1f2937",
            color: "#fff",
            padding: "12px 20px",
            borderRadius: 10,
            fontSize: 13,
            fontWeight: 500,
            boxShadow: "0 4px 16px rgba(0,0,0,0.2)",
            maxWidth: 360,
          }}
        >
          {toast}
        </div>
      )}

      <div style={{ maxWidth: 1100, margin: "0 auto", padding: "28px 16px" }}>
        {/* Header */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            marginBottom: 24,
            flexWrap: "wrap",
            gap: 12,
          }}
        >
          <div>
            <h1
              style={{
                fontSize: 22,
                fontWeight: 700,
                color: "#111827",
                margin: 0,
              }}
            >
              Payment Approvals
            </h1>
            <p style={{ fontSize: 13, color: "#6b7280", margin: "4px 0 0" }}>
              SympoTech Admin — UTR Verification Dashboard
            </p>
          </div>
          <button
            onClick={fetchUsers}
            style={{
              padding: "8px 18px",
              backgroundColor: "#4f46e5",
              color: "#fff",
              border: "none",
              borderRadius: 8,
              fontSize: 13,
              fontWeight: 600,
              cursor: "pointer",
            }}
          >
            ↻ Refresh
          </button>
        </div>

        {/* Stat Cards */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(4,1fr)",
            gap: 12,
            marginBottom: 24,
          }}
        >
          {[
            {
              label: "Total",
              value: counts.all,
              color: "#4f46e5",
              bg: "#eef2ff",
            },
            {
              label: "Pending",
              value: counts.pending,
              color: "#d97706",
              bg: "#fefce8",
            },
            {
              label: "Approved",
              value: counts.approved,
              color: "#16a34a",
              bg: "#f0fdf4",
            },
            {
              label: "Rejected",
              value: counts.rejected,
              color: "#dc2626",
              bg: "#fef2f2",
            },
          ].map(({ label, value, color, bg }) => (
            <div
              key={label}
              style={{
                background: bg,
                borderRadius: 12,
                padding: "16px 18px",
                border: `1px solid ${color}22`,
              }}
            >
              <div style={{ fontSize: 12, color: "#6b7280", marginBottom: 4 }}>
                {label}
              </div>
              <div style={{ fontSize: 28, fontWeight: 700, color }}>
                {value}
              </div>
            </div>
          ))}
        </div>

        {/* Bulk Auto-Approve Panel */}
        <div
          style={{
            background: "#fff",
            borderRadius: 12,
            padding: "16px 20px",
            marginBottom: 20,
            border: "1px solid #e5e7eb",
            display: "flex",
            alignItems: "center",
            gap: 16,
            flexWrap: "wrap",
          }}
        >
          <div style={{ flex: 1, minWidth: 200 }}>
            <div
              style={{
                fontSize: 13,
                fontWeight: 600,
                color: "#111827",
                marginBottom: 4,
              }}
            >
              🤖 Smart Bulk Auto-Approve
            </div>
            <div style={{ fontSize: 12, color: "#6b7280" }}>
              Auto-approve all pending users whose UTR score is ≥ threshold
            </div>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <label style={{ fontSize: 12, color: "#374151" }}>Min Score:</label>
            <input
              type="number"
              min="50"
              max="100"
              value={bulkScore}
              onChange={(e) => setBulkScore(Number(e.target.value))}
              style={{
                width: 60,
                padding: "6px 8px",
                borderRadius: 6,
                border: "1px solid #d1d5db",
                fontSize: 13,
              }}
            />
            <button
              onClick={handleBulkApprove}
              disabled={bulkLoading}
              style={{
                padding: "8px 18px",
                backgroundColor: bulkLoading ? "#9ca3af" : "#16a34a",
                color: "#fff",
                border: "none",
                borderRadius: 8,
                fontSize: 13,
                fontWeight: 600,
                cursor: bulkLoading ? "not-allowed" : "pointer",
              }}
            >
              {bulkLoading ? "Processing..." : `Bulk Approve (≥${bulkScore})`}
            </button>
          </div>
          <div
            style={{
              fontSize: 11,
              color: "#6b7280",
              width: "100%",
              marginTop: -8,
            }}
          >
            ⚠️ Only use after verifying with your bank app. Score ≥ 85 = very
            likely real UTR.
          </div>
        </div>

        {/* Filters + Search */}
        <div
          style={{
            display: "flex",
            gap: 8,
            marginBottom: 16,
            flexWrap: "wrap",
            alignItems: "center",
          }}
        >
          {["all", "pending", "approved", "rejected"].map((f) => (
            <button
              key={f}
              onClick={() => setFilter(f)}
              style={{
                padding: "6px 16px",
                borderRadius: 8,
                fontSize: 13,
                cursor: "pointer",
                fontWeight: 500,
                backgroundColor: filter === f ? "#4f46e5" : "#fff",
                color: filter === f ? "#fff" : "#6b7280",
                border:
                  filter === f ? "1px solid #4f46e5" : "1px solid #d1d5db",
              }}
            >
              {f.charAt(0).toUpperCase() + f.slice(1)} (
              {counts[f] ?? users.length})
            </button>
          ))}
          <input
            placeholder="Search name / UTR / email..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            style={{
              marginLeft: "auto",
              padding: "7px 14px",
              borderRadius: 8,
              border: "1px solid #d1d5db",
              fontSize: 13,
              width: 240,
              outline: "none",
            }}
          />
        </div>

        {/* Table */}
        {loading ? (
          <div
            style={{
              textAlign: "center",
              padding: "40px",
              color: "#6b7280",
              fontSize: 14,
            }}
          >
            Loading...
          </div>
        ) : (
          <div
            style={{
              background: "#fff",
              borderRadius: 12,
              border: "1px solid #e5e7eb",
              overflow: "hidden",
            }}
          >
            <table
              style={{
                width: "100%",
                borderCollapse: "collapse",
                fontSize: 13,
              }}
            >
              <thead>
                <tr style={{ backgroundColor: "#f9fafb" }}>
                  {[
                    "#",
                    "Name",
                    "UTR Number",
                    "Score",
                    "Event",
                    "Status",
                    "Actions",
                  ].map((h) => (
                    <th
                      key={h}
                      style={{
                        padding: "11px 14px",
                        textAlign: "left",
                        fontSize: 11,
                        fontWeight: 600,
                        color: "#6b7280",
                        borderBottom: "1px solid #e5e7eb",
                        whiteSpace: "nowrap",
                      }}
                    >
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {filtered.length === 0 ? (
                  <tr>
                    <td
                      colSpan={7}
                      style={{
                        textAlign: "center",
                        padding: 40,
                        color: "#9ca3af",
                      }}
                    >
                      No records found
                    </td>
                  </tr>
                ) : (
                  filtered.map((u, i) => (
                    <tr
                      key={u.id}
                      style={{ borderBottom: "1px solid #f3f4f6" }}
                    >
                      <td style={{ padding: "12px 14px", color: "#9ca3af" }}>
                        {i + 1}
                      </td>

                      <td style={{ padding: "12px 14px" }}>
                        <div style={{ fontWeight: 600, color: "#111827" }}>
                          {u.name}
                        </div>
                        <div style={{ fontSize: 11, color: "#9ca3af" }}>
                          {u.email}
                        </div>
                        <div style={{ fontSize: 11, color: "#9ca3af" }}>
                          {u.phone}
                        </div>
                      </td>

                      <td style={{ padding: "12px 14px" }}>
                        <code
                          style={{
                            fontSize: 12,
                            background: "#f3f4f6",
                            padding: "2px 7px",
                            borderRadius: 4,
                            color: "#374151",
                          }}
                        >
                          {u.utr_number}
                        </code>
                        {u.utr_flags && u.utr_flags.length > 0 && (
                          <div style={{ marginTop: 4 }}>
                            {u.utr_flags.slice(0, 2).map((flag, fi) => (
                              <div
                                key={fi}
                                style={{
                                  fontSize: 10,
                                  color: flag.startsWith("✅")
                                    ? "#16a34a"
                                    : "#d97706",
                                }}
                              >
                                {flag}
                              </div>
                            ))}
                          </div>
                        )}
                      </td>

                      <td style={{ padding: "12px 14px" }}>
                        {u.utr_score != null ? (
                          <span
                            style={{
                              display: "inline-block",
                              padding: "3px 10px",
                              borderRadius: 20,
                              fontSize: 12,
                              fontWeight: 700,
                              backgroundColor: scoreBg(u.utr_score),
                              color: scoreColor(u.utr_score),
                              border: `1px solid ${scoreBorder(u.utr_score)}`,
                            }}
                          >
                            {u.utr_score}/100
                          </span>
                        ) : (
                          <span style={{ color: "#9ca3af", fontSize: 12 }}>
                            N/A
                          </span>
                        )}
                      </td>

                      <td style={{ padding: "12px 14px", color: "#374151" }}>
                        {u.event_id}
                      </td>

                      <td style={{ padding: "12px 14px" }}>
                        <StatusBadge status={u.payment_status} />
                      </td>

                      <td style={{ padding: "12px 14px" }}>
                        {u.payment_status === "pending" ? (
                          <div
                            style={{
                              display: "flex",
                              gap: 6,
                              flexWrap: "wrap",
                            }}
                          >
                            <button
                              onClick={() =>
                                handleAction(u.id, "approved", u.name)
                              }
                              style={{
                                padding: "5px 12px",
                                borderRadius: 7,
                                fontSize: 12,
                                fontWeight: 600,
                                cursor: "pointer",
                                border: "1px solid #86efac",
                                backgroundColor: "#f0fdf4",
                                color: "#166534",
                              }}
                            >
                              Approve
                            </button>
                            <button
                              onClick={() =>
                                handleAction(u.id, "rejected", u.name)
                              }
                              style={{
                                padding: "5px 12px",
                                borderRadius: 7,
                                fontSize: 12,
                                fontWeight: 600,
                                cursor: "pointer",
                                border: "1px solid #fca5a5",
                                backgroundColor: "#fef2f2",
                                color: "#b91c1c",
                              }}
                            >
                              Reject
                            </button>
                            <button
                              onClick={() => handleReanalyze(u.id, u.name)}
                              style={{
                                padding: "5px 10px",
                                borderRadius: 7,
                                fontSize: 12,
                                fontWeight: 500,
                                cursor: "pointer",
                                border: "1px solid #bfdbfe",
                                backgroundColor: "#eff6ff",
                                color: "#1e40af",
                              }}
                              title="Re-run UTR analysis"
                            >
                              🔬
                            </button>
                          </div>
                        ) : (
                          <span style={{ color: "#9ca3af", fontSize: 12 }}>
                            {u.payment_status === "approved"
                              ? "✅ Done"
                              : "❌ Rejected"}
                          </span>
                        )}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        )}

        <div
          style={{
            marginTop: 16,
            fontSize: 11,
            color: "#9ca3af",
            textAlign: "center",
          }}
        >
          UTR scores: 75–100 = likely real · 45–74 = suspicious · 0–44 = likely
          fake
        </div>
      </div>
    </div>
  );
}
